-- =====================================================================================================================
-- Enrollzy: database changes of 27-31 Oct 2026 (career roadmap, experts, booking, dashboards, OTP security, expert login)
-- Made 29 Oct 2026 from the 15 new migrations in enrollzy_backend/database/migrations, by running them on the
-- 24 Oct 2026 backup (enrollzy-2026-10-24-093036.sql) and writing down every change they made, in order.
--
-- Import ONCE into a database that does not have these changes yet (as at the 24 Oct backup): phpMyAdmin > Import,
-- or  mysql -u USER -p DATABASE < db_changes_2026_10_29.sql
-- Take a backup first. Works on MySQL 5.7+/8 and MariaDB 10.3+.
--
-- * Statements stop on the first error: if a column or table already exists the database already has that part.
-- * The career roadmap content (section 2) sets items by id as they were on 24 Oct. Items added or edited on the live
--   site since then keep their own rows, but an item edited since then gets the content below. New items carry their
--   id: if that id is already used, the import stops there instead of linking content to the wrong item.
-- * No test data: Anup Kumar Vishal's dummy profile, test bookings and the test mobile are not here
--   (AnupDummyProfileSeeder, local only).
-- * The last section records the migrations as run, so "php artisan migrate" does not run them again.
-- * After importing, add each expert's mobile number in the CRM (Experts > Edit): experts sign in on the website with
--   OTP to it.
-- =====================================================================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. 2026_10_27_100000_extend_career_roadmap_module
--    Career roadmap: new fields on categories, stages and items; the careers master table; career page content in settings.
-- ---------------------------------------------------------------------------------------------------------------------
alter table `career_roadmap_categories` add `sort_order` int not null default '0' after `slug`;
alter table `career_roadmap_categories` add `description` text null after `sort_order`;
alter table `career_roadmap_stages` add `sort_order` int not null default '0' after `slug`;
alter table `career_roadmap_stages` add `key_points` text null after `description`;
alter table `career_roadmap_sub_modules` add `sort_order` int not null default '0' after `slug`;
alter table `career_roadmap_sub_modules` add `roadmap_type` varchar(30) null after `sort_order`;
alter table `career_roadmap_sub_modules` add `item_type` varchar(20) null after `roadmap_type`;
alter table `career_roadmap_sub_modules` add `url_slug` varchar(120) null after `item_type`;
alter table `career_roadmap_sub_modules` add `summary` varchar(300) null after `title`;
alter table `career_roadmap_sub_modules` add `eligibility` text null after `long_description`;
alter table `career_roadmap_sub_modules` add `conducted_by` varchar(190) null after `eligibility`;
alter table `career_roadmap_sub_modules` add `when_text` varchar(190) null after `conducted_by`;
alter table `career_roadmap_sub_modules` add `duration` varchar(100) null after `when_text`;
alter table `career_roadmap_sub_modules` add `fee` varchar(255) null after `duration`;
alter table `career_roadmap_sub_modules` add `salary` varchar(255) null after `fee`;
alter table `career_roadmap_sub_modules` add `official_url` varchar(500) null after `salary`;
alter table `career_roadmap_sub_modules` add `exam_id` bigint unsigned null after `official_url`;
alter table `career_roadmap_sub_modules` add `course_id` bigint unsigned null after `exam_id`;
alter table `career_roadmap_sub_modules` add `scholarship_id` bigint unsigned null after `course_id`;
alter table `career_roadmap_sub_modules` add `career_id` bigint unsigned null after `scholarship_id`;
alter table `career_roadmap_sub_modules` add `subjects` text null after `career_id`;
alter table `career_roadmap_sub_modules` add `who_should` text null after `subjects`;
alter table `career_roadmap_sub_modules` add `closes` text null after `who_should`;
alter table `career_roadmap_sub_modules` add `career_ids` json null after `closes`;
alter table `career_roadmap_sub_modules` add `meta_title` varchar(255) null after `career_ids`;
alter table `career_roadmap_sub_modules` add `meta_description` varchar(500) null after `meta_title`;
alter table `career_roadmap_sub_modules` add index `crsm_tree_idx`(`stage_id`, `parent_id`, `sort_order`);
create table `careers` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `slug` varchar(255) not null, `icon` varchar(20) null, `summary` varchar(300) null, `about` text null, `stream` varchar(255) null, `route` json null, `exams` json null, `course_ids` json null, `salary` varchar(255) null, `recruiters` text null, `show_for` json null, `sort_order` int not null default '0', `status` tinyint(1) not null default '1', `meta_title` varchar(255) null, `meta_description` varchar(500) null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `careers` add unique `careers_slug_unique`(`slug`);
alter table `settings` add `career_page_content` json null;

-- ---------------------------------------------------------------------------------------------------------------------
