update `settings` set `career_page_content` = '{\n    \"meta_title\": \"All career roadmaps · Exams, courses & careers | Enrollzy\",\n    \"meta_description\": \"Free career roadmaps: the stream, exam, counselling, course and years each step takes, for doctor, engineer, CA, lawyer, civil servant and more. Download any roadmap as a PDF.\",\n    \"trust\": [\n        \"Counselling is free\",\n        \"DPIIT-recognised platform\",\n        \"Real counsellors on call\"\n    ],\n    \"lead_badge\": \"Free · takes 30 seconds\",\n    \"lead_title\": \"Get your personal roadmap from a career expert\",\n    \"lead_text\": \"Tell us your class. A counsellor calls you with two or three paths that fit your marks and budget.\",\n    \"faq_title\": \"Career roadmap FAQs\",\n    \"faqs\": [\n        {\n            \"q\": \"When should I start planning my career?\",\n            \"a\": \"Class 9 or 10 is the best time to start, because the stream you pick after Class 10 decides which entrance exams you can take. Earlier classes are for exploring interests.\"\n        },\n        {\n            \"q\": \"Can I become a doctor if I took PCM?\",\n            \"a\": \"Not through NEET UG unless you add Biology. NEET needs Physics, Chemistry and Biology in Class 12. Some boards let you take Biology as an additional subject.\"\n        },\n        {\n            \"q\": \"Is commerce only for CA?\",\n            \"a\": \"No. Commerce also leads to B.Com, BBA, economics, banking, company secretary and management. CA, CS and CMA are the professional routes.\"\n        },\n        {\n            \"q\": \"How accurate are these durations?\",\n            \"a\": \"They are typical durations for full-time study in India. Your actual time can be longer if you take a drop year, repeat an exam or study part-time.\"\n        }\n    ],\n    \"learn_title\": \"Read, ask and discuss\",\n    \"learn_sub\": \"Guides from our counsellors and questions from students like you on Ask Enrollzy.\",\n    \"topics\": [\n        {\n            \"label\": \"Stream selection\",\n            \"keywords\": [\n                \"stream\",\n                \"class 10\",\n                \"class 11\",\n                \"PCM\",\n                \"PCB\",\n                \"humanities\",\n                \"after 10th\"\n            ]\n        },\n        {\n            \"label\": \"NEET and medicine\",\n            \"keywords\": [\n                \"NEET\",\n                \"MBBS\",\n                \"medical\",\n                \"medicine\",\n                \"doctor\",\n                \"nursing\",\n                \"pharmacy\"\n            ]\n        },\n        {\n            \"label\": \"JEE and engineering\",\n            \"keywords\": [\n                \"JEE\",\n                \"engineering\",\n                \"B.Tech\",\n                \"BTech\",\n                \"IIT\",\n                \"NIT\"\n            ]\n        },\n        {\n            \"label\": \"CA and commerce\",\n            \"keywords\": [\n                \"CA\",\n                \"chartered\",\n                \"commerce\",\n                \"B.Com\",\n                \"BCom\",\n                \"BBA\",\n                \"CMA\"\n            ]\n        },\n        {\n            \"label\": \"MBA and management\",\n            \"keywords\": [\n                \"MBA\",\n                \"CAT\",\n                \"management\",\n                \"PGDM\"\n            ]\n        },\n        {\n            \"label\": \"AI, data and tech\",\n            \"keywords\": [\n                \"AI\",\n                \"artificial intelligence\",\n                \"data\",\n                \"BCA\",\n                \"python\",\n                \"coding\"\n            ]\n        },\n        {\n            \"label\": \"Law\",\n            \"keywords\": [\n                \"law\",\n                \"CLAT\",\n                \"LLB\",\n                \"lawyer\"\n            ]\n        },\n        {\n            \"label\": \"Government jobs\",\n            \"keywords\": [\n                \"UPSC\",\n                \"IAS\",\n                \"civil services\",\n                \"government job\",\n                \"SSC\",\n                \"NDA\"\n            ]\n        },\n        {\n            \"label\": \"Design\",\n            \"keywords\": [\n                \"design\",\n                \"NID\",\n                \"NIFT\",\n                \"UCEED\"\n            ]\n        }\n    ],\n    \"ask_label\": \"Ask the community or a counsellor\",\n    \"ask_placeholder\": \"e.g. Can I do BCA after Commerce without Maths?\",\n    \"ask_note\": \"Counsellors usually answer here, and you can get a call if you want one.\",\n    \"list_title\": \"All career roadmaps,\",\n    \"list_title_em\": \"stage by stage\",\n    \"list_lede\": \"Pick your stage and class, then the path that interests you. Each roadmap shows the exams, courses, scholarships and careers it opens, step by step, with a free PDF.\"\n}' where `id` = 1;

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. 2026_10_27_110000_create_career_categories_table
--    Career categories (medical, engineering, ...) and each career linked to its category.
-- ---------------------------------------------------------------------------------------------------------------------
create table `career_categories` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `slug` varchar(255) not null, `icon` varchar(20) null, `description` varchar(300) null, `sort_order` int not null default '0', `status` tinyint(1) not null default '1', `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `career_categories` add unique `career_categories_slug_unique`(`slug`);
alter table `careers` add `category_id` bigint unsigned null after `icon`;
alter table `careers` add index `careers_category_id_index`(`category_id`);
